import java.util.ArrayDeque;

public class Main {
    static byte[] data;
    static int pos = 0;

    static boolean skipSpace() {
        while (pos < data.length && (data[pos] & 0xff) <= ' ') pos++;
        return pos < data.length;
    }

    static String token() {
        skipSpace();
        int s = pos;
        while (pos < data.length && (data[pos] & 0xff) > ' ') pos++;
        return new String(data, s, pos - s, java.nio.charset.StandardCharsets.UTF_8);
    }

    static long num() {
        skipSpace();
        boolean neg = false;
        if (pos < data.length && (data[pos] == '-' || data[pos] == '+')) neg = data[pos++] == '-';
        long v = 0;
        while (pos < data.length && data[pos] >= '0' && data[pos] <= '9') v = v * 10 + (data[pos++] - '0');
        return neg ? -v : v;
    }

    public static void main(String[] args) throws Exception {
        data = System.in.readAllBytes();
        int n = (int) num();
        ArrayDeque<Long> active = new ArrayDeque<>();  // finish times of people still in the system
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long arrival = num();
            // Someone finishing exactly at this arrival has already left.
            while (!active.isEmpty() && active.peekFirst() <= arrival) active.pollFirst();
            if (i > 0) out.append(' ');
            if (active.size() > 10) {
                out.append("null");
                continue;
            }
            long start = active.isEmpty() ? arrival : Math.max(arrival, active.peekLast());
            out.append(start);
            active.addLast(start + 30);
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func skipSpace() bool {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	return pos < len(data)
}

func token() string {
	skipSpace()
	s := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[s:pos])
}

func num() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && (data[pos] == '-' || data[pos] == '+') {
		neg = data[pos] == '-'
		pos++
	}
	var v int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		v = v*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(num())
	active := []int64{} // finish times of people still in the system
	head := 0
	out := []byte{}
	for i := 0; i < n; i++ {
		arrival := num()
		// Someone finishing exactly at this arrival has already left.
		for head < len(active) && active[head] <= arrival {
			head++
		}
		if i > 0 {
			out = append(out, ' ')
		}
		if len(active)-head > 10 {
			out = append(out, "null"...)
			continue
		}
		start := arrival
		if head < len(active) {
			start = max(arrival, active[len(active)-1])
		}
		out = strconv.AppendInt(out, start, 10)
		active = append(active, start+30)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
